const BASE = 'https://www.sankavollerei.web.id/comic/softkomik'

const headers = {
  'user-agent': 'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36',
  'accept': 'application/json',
  'referer': 'https://riztoon.my.id/'
}

async function api(path, timeout = 15000) {
  const ctrl = new AbortController()
  const timer = setTimeout(() => ctrl.abort(), timeout)
  try {
    const r = await fetch(`${BASE}${path}`, { signal: ctrl.signal, headers })
    if (!r.ok) throw new Error(`API ${r.status}`)
    const j = await r.json()
    if (j.success === false) throw new Error(j.message || j.error || 'API error')
    return j
  } finally {
    clearTimeout(timer)
  }
}

function normalizeComic(c) {
  return {
    title: c.title,
    slug: c.slug,
    image: c.image || c.imageSrc || c.cover || c.thumbnail || '',
    rating: typeof c.rating === 'object' && c.rating !== null ? String(c.rating.average ?? '') : c.rating || undefined,
    chapter: c.chapter,
    latestChapter: typeof c.latestChapter === 'number' ? `Chapter ${c.latestChapter}` : c.latestChapter,
    type: c.type
  }
}

function normalizePagination(p, page, len) {
  if (!p) return { currentPage: page, hasNextPage: len >= 20, nextPage: len >= 20 ? page + 1 : null }
  const hasNext = !!(p.hasNext ?? p.hasNextPage ?? p.nextPage)
  return {
    currentPage: p.currentPage ?? page,
    hasNextPage: hasNext,
    nextPage: p.nextPage ?? (hasNext ? (p.currentPage ?? page) + 1 : null),
    totalPages: p.maxPage ?? p.totalPages
  }
}

async function home() {
  const { data } = await api('/home')
  return {
    trending: (data.trending || []).map(normalizeComic),
    latestUpdates: (data.latestUpdates || data.latest || []).map(normalizeComic)
  }
}

async function library(page = 1) {
  const d = await api(`/library?page=${page}&sort=popular`)
  const items = (d.data || []).map(normalizeComic)
  return { results: items, pagination: normalizePagination(d.pagination, page, items.length) }
}

async function ongoing(page = 1) {
  const d = await api(`/ongoing?page=${page}`)
  const items = (d.data || []).map(normalizeComic)
  return { results: items, pagination: normalizePagination(d.pagination, page, items.length) }
}

async function completed(page = 1) {
  const d = await api(`/completed?page=${page}`)
  const items = (d.data || []).map(normalizeComic)
  return { results: items, pagination: normalizePagination(d.pagination, page, items.length) }
}

async function genres() {
  const { data } = await api('/genres')
  return (data || []).map(g => ({
    label: g.title || g.name || g.slug,
    value: String(g.id ?? g.slug ?? g.title),
    slug: g.slug || g.title
  }))
}

async function genre(slug, page = 1) {
  const d = await api(`/genre/${encodeURIComponent(slug)}`)
  const items = (d.data || []).map(normalizeComic)
  return { results: items, pagination: normalizePagination(d.pagination, page, items.length) }
}

async function search(query, page = 1) {
  const d = await api(`/search?q=${encodeURIComponent(query)}`)
  const items = (d.data || d.komikList || []).map(normalizeComic)
  return { results: items, pagination: normalizePagination(d.pagination, page, items.length) }
}

async function detail(slug) {
  const d = await api(`/detail/${slug}`, 20000)
  const m = d.data || d.detail || {}
  const chapters = (m.chapters || m.chapter_list || m.chapterList || []).map(ch => {
    const num = String(ch.chapter ?? ch.number ?? ch.slug ?? '').replace(/^.*chapter[-\s]*/i, '')
    return {
      title: ch.title || (num ? `Chapter ${num}` : String(ch.slug ?? '')),
      slug: `${slug}-chapter-${num}`,
      date: ch.date || ch.updatedAt || ch.time
    }
  })
  return {
    title: m.title || slug,
    alternative: m.titleAlt || m.alternative || m.otherTitle,
    image: m.image || m.cover || m.imageSrc,
    rating: typeof m.rating === 'object' && m.rating ? String(m.rating.average ?? '') : m.rating,
    synopsis: m.synopsis || m.description,
    type: m.type,
    author: m.author,
    status: m.status,
    genres: (m.genres || []).map(g => typeof g === 'string' ? { name: g, slug: g } : { name: g.title || g.name, slug: g.slug || g.name }),
    chapters
  }
}

