async function chapterStream(slug) {
  const match = slug.match(/^(.+?)-chapter-(.+)$/i)
  let data
  if (match) {
    const [, mangaSlug, chNum] = match
    const variants = [...new Set([chNum, chNum.replace(/[^\d]/g, ''), chNum.replace(/[^\d]/g, '').padStart(3, '0'), chNum.replace(/^0+/, '')])].filter(Boolean)
    let lastErr
    for (const v of variants) {
      try {
        data = await api(`/chapter/${mangaSlug}/${v}`, 20000)
        break
      } catch (e) { lastErr = e }
    }
    if (!data) throw lastErr || new Error('Chapter not found')
  } else {
    data = await api(`/chapter/${slug}`, 20000)
  }
  const ch = data.data || data
  const images = (ch.images || ch.image || ch.chapter_image || []).map(i => typeof i === 'string' ? i : i?.url || i?.src || '').filter(Boolean)
