  const [cmd, ...rest] = args
  try {
    let result
    switch (cmd) {
      case 'home': result = await home(); break
      case 'library': result = await library(Number(rest[0]) || 1); break
      case 'ongoing': result = await ongoing(Number(rest[0]) || 1); break
      case 'completed': result = await completed(Number(rest[0]) || 1); break
      case 'genres': result = await genres(); break
      case 'genre': result = await genre(rest[0], Number(rest[1]) || 1); break
      case 'search': result = await search(rest.join(' ')); break
      case 'detail': result = await detail(rest[0]); break
      case 'chapter': result = await chapter(rest[0]); break
      case 'chapter-stream': await chapterStream(rest[0]); return
      case 'top': result = await topWeekly(); break
      case 'recommend': result = await recommendation(); break
      default:
        console.error(`Unknown command: ${cmd}`)
        process.exit(1)
    }
    console.log(JSON.stringify(result, null, 2))
  } catch (err) {
    console.log(JSON.stringify({ status: false, message: err.message }, null, 2))
    process.exit(1)
  }
